import sys, json, re, os, collections, urllib.parse
sys.path.insert(0, __file__.rsplit('/',1)[0])
from ub_lib import ROOT, now, load_manifest, save_manifest, sha256
from crawl_lib import canon_key
NOW = now()
J = lambda p: json.load(open(os.path.join(ROOT, p)))
sm = J("evidence/area_d/crawl-sitemap.json"); ex = J("evidence/area_d/crawl-extra.json"); an = J("evidence/area_d/analysis.json")
rows = {r["key"]: r for r in an["rows"]}
nap = J("nap-corrections.json"); L = {l["key"]: l for l in nap["listings_checked"]}; st = nap["stats"]
idx = J("index-intended.json"); lp = J("link-plan.json"); rm = J("redirect-map.json")
gsc = json.load(open(ROOT + "/../baseline/2026-10-01-gsc-export-90d.json")); gsc_by = {canon_key(p["keys"][0]): p for p in gsc["pages"]}
insp = J("evidence/area_e/inspect-results.json")

# ---- HWG classification (no legal judgement: only sorting for the human)
NEG = re.compile(r"\b(keine?n?|ohne|nicht|nie|kein)\b", re.I)
hw = collections.defaultdict(lambda: {"negated_or_disclaimer": [], "selbstheilung": [], "other": []})
for u, r in sm.items():
    for m in r.get("hwg_matches", []):
        c = m["context"]; low = c.lower()
        mid = low[len(low)//2-40: len(low)//2+40]
        if "selbstheil" in mid: cat = "selbstheilung"
        elif NEG.search(mid): cat = "negated_or_disclaimer"
        else: cat = "other"
        hw[urllib.parse.urlparse(u).path][cat].append({"term": m["term"], "context": c})
json.dump({"note": "Regex hits only. Sorted into three buckets for the human reviewer. NOT a legal judgement.", "pages": hw, "collected_at": NOW}, open(ROOT + "/evidence/area_d/hwg-matches.json", "w"), ensure_ascii=False, indent=1)
mf = load_manifest()
def regfile(eid, rel, tool, req, note=""):
    b = open(os.path.join(ROOT, rel), "rb").read()
    mf["evidence"] = [e for e in mf["evidence"] if e["id"] != eid]
    mf["evidence"].append({"id": eid, "file": rel, "sha256": sha256(b), "bytes": len(b), "tool": tool, "request": req, "cost_eur": 0, "collected_at": NOW, "note": note})
regfile("EV-D-hwg", "evidence/area_d/hwg-matches.json", "local regex scan (crawl_lib.HWG) over visible text, title and meta description", "scan of 89 sitemap pages", "human review only")
save_manifest(mf)
other_pages = {p: v["other"] for p, v in hw.items() if v["other"]}

