ITEMS = []; CNT = collections.Counter()
def H(area, entity, check, item, why, sev, action, actor, effort, conf, ev, target="", detail="", destructive=False, approval="proposed", verify="", depends=None, tool="", refetch=None, source_field=None, hint="", client_safe=True):
    CNT[area] += 1
    it = {"id": f"H-{area}-{CNT[area]:03d}", "area": area, "entity": entity, "item": item, "why": why, "check_id": check, "source_field": source_field, "target": target,
          "severity": sev, "action": action, "action_detail": detail, "actor": actor, "effort": effort, "destructive": destructive, "approval": approval,
          "approved_by": None, "approved_at": None, "wave": None, "snapshot_id": None, "rollback": None, "before": None, "after": None, "verify_check": verify, "done_at": None,
          "confidence": conf, "collected_at": NOW, "source_tool": tool, "evidence_ids": ev, "refetch": refetch or {}, "depends_on": depends or [], "drilldown_hint": hint, "client_safe": client_safe}
    ITEMS.append(it); return it["id"]
